import type { Geldbedrag } from "#types";
import Polis from "./polis.ts";
import { Traverse } from "@asr-tools/utils";

export default class GaragePolis extends Polis {
    constructor(...args: ConstructorParameters<typeof Polis>) {
        super(...args);
        if (this.data.productExtId !== "garage") {
            throw new Error(`Polis ${this.polisnummer} is geen garagepolis`);
        }
    }

    /** Null indien afwezig */
    get G1() { return this.dekking("G1"); }
    /** Null indien afwezig */
    get G2() { return this.dekking("G2"); }
    /** Null indien afwezig */
    get G4() { return this.dekking("G4"); }
    /** Null indien afwezig */
    get G5() { return this.dekking("G5"); }

    get omzet() { return this.veld<Geldbedrag>("polGarageLegOmzetBd"); } // todo: LEG
    get activiteit() { return this.veld("polGarageLegActiviteitAn"); } // todo: LEG

    get heeftRDB() {
        return this.clausules.some(
            c => c.externalIdentifier === "clsGarageRegistratieDekkingBedrijfsvoorraad"
        );
    }
    get isLandbouwmechanisatie() {
        return this.heeftClausule("V567")
            || this.clausules.some(c => c.externalIdentifier === "clsGarageLandbouwmechanisatiebedrijfG1")
            || !!this.activiteit?.startsWith("Landbouwmechanisatiebedrijf");
    }

    private dekking(code: string) {
        const id = this.isConversie ? `dekGarageLeg${code}` : `dekGarage${code}`;
        return Traverse.matchByIdentifier(this.details.policyInstanceCoverageList, id);
    }
}